pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

var users = pm.response.json();

pm.test("Response is a non-empty array", function () {
    pm.expect(users).to.be.an("array");
    pm.expect(users.length).to.be.above(0);
});

pm.test("Each user has id, name and email", function () {
    users.forEach(function (user) {
        pm.expect(user).to.have.property("id");
        pm.expect(user).to.have.property("name");
        pm.expect(user).to.have.property("email");
    });
})
pm.collectionVariables.set("userId", users[0].id);
pm.collectionVariables.set("userData", JSON.stringify(users[0]));

var user = JSON.parse(pm.collectionVariables.get("userData"));

var stamp = Date.now();
var newName = "Updated User " + stamp;
var newEmail = "updated" + stamp + "@example.com";
var newCompany = "Company " + stamp;

user.name = newName;
user.email = newEmail;
user.company.name = newCompany;

pm.collectionVariables.set("newName", newName);
pm.collectionVariables.set("putBody", JSON.stringify(user));

pm.test("Status code is 200", function () {
    pm.response.to.have.status(200);
});

var body = pm.response.json();

pm.test("ID matches the saved ID", function () {
    pm.expect(body.id).to.eql(Number(pm.collectionVariables.get("userId")));
});
